import { atom, read, update } from 'claude-code'
import type { ProcessRunResult, Register } from 'claude-code'

import { NOW_PLAYING_ARGV, POLL_MS, TICK_MS, isSameTrack, label, labelRoom, parseTrack } from './spotify'
import type { Track } from './spotify'

const isHidden = atom({ plugin: 'spotify', key: 'isHidden' } as const, false)

const asError = (error: unknown): Error => (error instanceof Error ? error : new Error(String(error)))

export const register: Register = on => {
  let track: Track | null = null
  let isTurnRunning = false
  let isPolling = false
  let ticksToPoll = 0
  // Why the last poll could not ask Spotify, for /spotify to say; null when it could.
  let problem: string | null = null

  // Takes in what osascript answered; true when the song to show changed.
  function hear(answer: ProcessRunResult | Error): boolean {
    let playing: Track | null = null
    if (answer instanceof Error) {
      // No osascript (not macOS), or it ran past the engine's 30 s limit.
      problem = answer.message
    } else if (answer.exitCode !== 0) {
      problem = answer.stderr.trim() || `osascript exited with ${answer.exitCode}`
    } else {
      problem = null
      playing = parseTrack(answer.stdout)
    }
    if (isSameTrack(track, playing)) return false
    track = playing
    return true
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'spotify',
      description: 'Show or hide the song Spotify is playing beside the spinner',
    })
    // Only while a turn runs: between turns there is no spinner to put it in.
    // No timeout of our own on osascript: the first run waits on the macOS
    // Automation prompt, and killing it would raise the prompt again.
    $.clock.every(TICK_MS, () => {
      if (!isTurnRunning || isPolling || --ticksToPoll > 0) return
      ticksToPoll = POLL_MS / TICK_MS
      isPolling = true
      void (async () => {
        try {
          if (await read($, isHidden)) return
          if (hear(await $.process.run(NOW_PLAYING_ARGV).catch(asError))) $.ui.invalidate('ui.render')
        } finally {
          isPolling = false
        }
      })()
    })
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    isTurnRunning = true
    ticksToPoll = 0
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    // A subagent's turn ends here too, inside the main turn, so only the main
    // loop's end stops the polls. The song is dropped rather than shown stale
    // when the next turn starts.
    if (e.agentId === undefined) {
      isTurnRunning = false
      track = null
    }
    return next(e)
  })

  on('command.run', { command: 'spotify' }, async $ => {
    const hidden = await update($, isHidden, was => !was)
    if (!hidden) hear(await $.process.run(NOW_PLAYING_ARGV).catch(asError))
    $.ui.invalidate('ui.render')
    if (hidden) return { text: 'The spinner no longer shows what Spotify plays.' }
    if (track !== null) return { text: `The spinner shows what Spotify plays: ${label(track, Infinity)}` }
    if (problem !== null) return { text: `The spinner shows what Spotify plays, but Spotify could not be asked: ${problem}` }
    return { text: 'The spinner shows what Spotify plays, once something plays.' }
  })

  // The song goes after the engine's ellipsis rather than in place of the
  // word, so the word, elapsed time and tokens stay, and a mod drawing its
  // own spinner (halloween) still draws the suffix it is handed.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (track === null || (await read($, isHidden))) return next(e)
    const text = e.props.message ?? e.props.word
    // The engine leaves its ellipsis off a text that already ends in one.
    const ellipsis = text.endsWith('…') ? '' : e.props.suffix
    const suffix = `${ellipsis} ${label(track, labelRoom(e.viewport?.columns))}`
    return next({ ...e, props: { ...e.props, suffix } })
  })
}

