export type Track = { name: string; artist: string }

// Often enough to catch a skip within a few seconds, rarely enough that the
// osascript it starts (about 0.1 s) goes unnoticed.
export const POLL_MS = 5000
// How soon a turn that has just started asks: the clock checks every tick
// whether a poll is due.
export const TICK_MS = 1000

// JXA rather than AppleScript: `Application('Spotify')` neither launches
// Spotify nor, where it is not installed, opens a "Where is Spotify?" dialog,
// and a `tell application "Spotify"` block does one or the other.
const NOW_PLAYING = `
const spotify = Application('Spotify')
if (!spotify.running() || spotify.playerState() !== 'playing') {
  'null'
} else {
  const track = spotify.currentTrack
  JSON.stringify({ name: track.name(), artist: track.artist() })
}`

export const NOW_PLAYING_ARGV = ['osascript', '-l', 'JavaScript', '-e', NOW_PLAYING] as const

// What the spinner draws besides the label (its glyph, the word, elapsed
// time, tokens), so a long title is cut rather than wrapping the line.
const SPINNER_COLUMNS = 60
const MIN_LABEL = 16
const MAX_LABEL = 60
const LABEL_WITHOUT_VIEWPORT = 40

/**
 * The track osascript printed, or null when nothing is playing or the output
 * is not a track (it comes from another process, so nothing is assumed).
 */
export function parseTrack(stdout: string): Track | null {
  let value: unknown
  try {
    value = JSON.parse(stdout)
  } catch {
    return null
  }
  if (typeof value !== 'object' || value === null) return null
  const { name, artist } = value as Record<string, unknown>
  if (typeof name !== 'string' || name.trim() === '') return null
  return { name: name.trim(), artist: typeof artist === 'string' ? artist.trim() : '' }
}

export function isSameTrack(a: Track | null, b: Track | null): boolean {
  return a?.name === b?.name && a?.artist === b?.artist
}

/**
 * How many columns the label may take on a terminal this wide.
 */
export function labelRoom(columns: number | undefined): number {
  if (columns === undefined) return LABEL_WITHOUT_VIEWPORT
  return Math.min(MAX_LABEL, Math.max(MIN_LABEL, columns - SPINNER_COLUMNS))
}

/**
 * `♫ Song · Artist`, cut with an ellipsis to fit `room` columns.
 */
export function label(track: Track, room: number): string {
  const text = track.artist === '' ? track.name : `${track.name} · ${track.artist}`
  const chars = [...`♫ ${text}`]
  return chars.length <= room ? chars.join('') : `${chars.slice(0, room - 1).join('').trimEnd()}…`
}

